import string


def normalize(cells):
    m = min(cells)
    return tuple(sorted((r - m[0], c - m[1]) for r, c in cells))


# The three-cell L-tromino is a 2x2 square with one cell removed: 4 orientations.
BASE = [(0, 0), (0, 1), (1, 0), (1, 1)]
SHAPES = set()
for skip in range(4):
    SHAPES.add(normalize([BASE[i] for i in range(4) if i != skip]))
SHAPES = sorted(SHAPES)


def solve(n):
    """Exhaustive backtracking: cover the first empty cell in row-major order.
    Any tromino covering that cell must have it as its row-major minimum,
    so trying every normalized L-shape anchored there is a complete search."""
    grid = [[None] * n for _ in range(n)]
    pieces = []

    def first_empty():
        for r in range(n):
            for c in range(n):
                if grid[r][c] is None:
                    return (r, c)
        return None

    def rec():
        pos = first_empty()
        if pos is None:
            return True
        r0, c0 = pos
        for sh in SHAPES:
            cells = [(r0 + dr, c0 + dc) for dr, dc in sh]
            if all(0 <= r < n and 0 <= c < n and grid[r][c] is None for r, c in cells):
                pid = len(pieces)
                pieces.append(cells)
                for r, c in cells:
                    grid[r][c] = pid
                if rec():
                    return True
                for r, c in cells:
                    grid[r][c] = None
                pieces.pop()
        return False

    ok = rec()
    return ok, grid, pieces


def verify_tiling(n, grid, pieces):
    """Check that the pieces are L-trominoes, disjoint, and cover the n x n square."""
    seen = set()
    for cells in pieces:
        if len(cells) != 3 or len(set(cells)) != 3:
            return False
        if normalize(cells) not in SHAPES:
            return False
        for r, c in cells:
            if not (0 <= r < n and 0 <= c < n):
                return False
            if (r, c) in seen:
                return False
            seen.add((r, c))
    return len(seen) == n * n and len(pieces) * 3 == n * n


